import type { PlayPack } from "./recurrence";
import currentRaw from "../data/play/current.json";
import v2026_11_0 from "../data/play/2026.11.0.json";
import tides2026 from "../data/play/tides/9445882-2026.json";
import tides2027 from "../data/play/tides/9445882-2027.json";
import tides2028 from "../data/play/tides/9445882-2028.json";
import tides2029 from "../data/play/tides/9445882-2029.json";

/**
 * Play content packs bundled into the Worker (schedule.md § 4.1, § 4.8; PD-11). All files are generated by
 * `scripts/build-play-content.mjs` into `src/data/play/` and never edited here:
 * - `current.json`: the newest pack, the only one `GET /v1/play/content` serves;
 * - `<version>.json`: the last ≤ 8 published packs, so a claim names the pack it was evaluated against (§ 7.2).
 * - `tides/9445882-<year>.json`: the NOAA high/low tables (§ 1.6).
 *
 * The Worker bundler cannot glob, so a newly published version or tide year needs one import line below.
 * `test/play-content.test.ts` lists the directory and fails until it is added; module load fails when
 * `current.json` names a version or tide year that is not imported.
 */
const PUBLISHED_FILES: unknown[] = [v2026_11_0];
const TIDE_FILES: Record<number, unknown> = { 2026: tides2026, 2027: tides2027, 2028: tides2028, 2029: tides2029 };

/** Kept published packs (product § 3.5 `keptConfigs`). */
export const MAX_PUBLISHED = 8;

export const CURRENT = currentRaw as unknown as PlayPack;

/** version → pack (≤ 8). The entry for `CURRENT.version` is `CURRENT` itself. */
export const PUBLISHED: ReadonlyMap<string, PlayPack> = (() => {
  const m = new Map<string, PlayPack>();
  for (const raw of PUBLISHED_FILES) {
    const p = raw as PlayPack;
    m.set(p.version, p.version === CURRENT.version ? CURRENT : p);
  }
  if (!m.has(CURRENT.version)) throw new Error(`play: current.json version ${CURRENT.version} has no bundled published copy (src/play/config.ts)`);
  if (m.size > MAX_PUBLISHED) throw new Error(`play: ${m.size} published packs bundled, at most ${MAX_PUBLISHED}`);
  return m;
})();

export const packByVersion = (version: string): PlayPack | null => PUBLISHED.get(version) ?? null;

export const TIDE_YEARS: readonly number[] = Object.keys(TIDE_FILES).map(Number);
{
  const named = ((CURRENT as { tides?: { years?: number[] } }).tides?.years ?? []).filter((y) => !TIDE_FILES[y]);
  if (named.length) throw new Error(`play: tide years ${named.join(", ")} named by current.json are not bundled (src/play/config.ts)`);
}

/** Tide table of `year` (the JSON object as generated), or null when not bundled. */
export const tidesFor = (year: number): unknown | null => TIDE_FILES[year] ?? null;

/** The body `GET /v1/play/content` serves: `current.json` re-serialized compactly (computed once per isolate). */
export const CONTENT_BODY = JSON.stringify(currentRaw);

let etagMemo: Promise<string> | null = null;

/** `"pc-<version>-<sha256(body)[0:12]>"` (schedule.md § 4.8). Immutable per deploy, so memoized per isolate. */
export function contentEtag(): Promise<string> {
  etagMemo ??= crypto.subtle.digest("SHA-256", new TextEncoder().encode(CONTENT_BODY)).then((buf) => {
    const hex = [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, "0")).join("");
    return `"pc-${CURRENT.version}-${hex.slice(0, 12)}"`;
  });
  return etagMemo;
}
